// Runtime alpha mask: retain the original portrait pixels, remove edge-connected
// background colors, and crop the lower portrait into a neck attachment.
const cache=new WeakMap();
export function headCutout(im){if(cache.has(im))return cache.get(im);if(!im.complete||!im.naturalWidth)return null;try{const c=document.createElement('canvas');c.width=128;c.height=112;const x=c.getContext('2d',{willReadFrequently:true});x.imageSmoothingEnabled=false;x.drawImage(im,0,0,im.width,im.height*.875,0,0,128,112);const d=x.getImageData(0,0,128,112),p=d.data,w=128,h=112;const samples=[[2,2],[125,2],[2,100],[125,100]].map(([a,b])=>{const n=(b*w+a)*4;return [p[n],p[n+1],p[n+2]]});const seen=new Uint8Array(w*h),queue=new Int32Array(w*h);let read=0,end=0;const push=n=>{if(n<0||n>=w*h||seen[n])return;seen[n]=1;const k=n*4;if(p[k+3]<20||samples.some(s=>(p[k]-s[0])**2+(p[k+1]-s[1])**2+(p[k+2]-s[2])**2<48**2)){queue[end++]=n;p[k+3]=0}};for(let a=0;a<w;a++){push(a);push((h-1)*w+a)}for(let b=0;b<h;b++){push(b*w);push(b*w+w-1)}while(read<end){const n=queue[read++];if(n%w)push(n-1);if(n%w<w-1)push(n+1);push(n-w);push(n+w)}x.putImageData(d,0,0);let left=w,top=h,right=0,bottom=0;for(let b=0;b<h;b++)for(let a=0;a<w;a++)if(p[(b*w+a)*4+3]>30){left=Math.min(left,a);right=Math.max(right,a);top=Math.min(top,b);bottom=Math.max(bottom,b)}const result={image:c,x:left,y:top,w:Math.max(1,right-left+1),h:Math.max(1,bottom-top+1)};cache.set(im,result);return result}catch{return null}}
